  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Northstar Retail — Home</title>
  <style>
    :root {
      color-scheme: light;
      --bg: #f5f7fb;
      --surface: #ffffff;
      --surface-2: #eef3ff;
      --surface-3: #f8fafc;
      --text: #182230;
      --muted: #5d6b82;
      --line: #d9e1ee;
      --brand: #0f62fe;
      --brand-dark: #0b4fcc;
      --brand-soft: #dfeaff;
      --accent: #ff7a59;
      --success: #1f8f5f;
      --shadow: 0 18px 50px rgba(24, 34, 48, 0.09);
      --radius-xl: 28px;
      --radius-lg: 22px;
      --radius-md: 16px;
      --radius-sm: 12px;
      --max: 1180px;
    }

    * {
      box-sizing: border-box;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      margin: 0;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at top left, rgba(15, 98, 254, 0.09), transparent 28%),
        radial-gradient(circle at 90% 12%, rgba(255, 122, 89, 0.08), transparent 18%),
        var(--bg);
      line-height: 1.5;
    }

    img {
      display: block;
      max-width: 100%;
    }

    a {
      color: inherit;
      text-decoration: none;
    }

    a:hover {
      text-decoration: underline;
      text-underline-offset: 0.18em;
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      z-index: 1000;
      padding: 0.875rem 1rem;
      border-radius: 999px;
      background: #fff;
      border: 1px solid var(--line);
      box-shadow: var(--shadow);
      transform: translateY(-160%);
      transition: transform 160ms ease;
    }

    .skip-link:focus,
    .skip-link:focus-visible {
      transform: translateY(0);
      outline: 3px solid var(--brand);
      outline-offset: 3px;
    }

    .shell {
      width: min(100%, var(--max));
      margin: 0 auto;
      padding: 0 1rem;
    }

    header {
      position: sticky;
      top: 0;
      z-index: 50;
      backdrop-filter: blur(18px);
      background: rgba(245, 247, 251, 0.84);
      border-bottom: 1px solid rgba(217, 225, 238, 0.8);
    }

    .topbar {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      min-height: 4.75rem;
    }

    .brand {
      display: inline-flex;
      align-items: center;
      gap: 0.75rem;
      font-weight: 800;
      letter-spacing: -0.03em;
      font-size: 1.05rem;
    }

    .brand-mark {
      width: 2.25rem;
      height: 2.25rem;
      border-radius: 14px;
      display: grid;
      place-items: center;
      color: #fff;
      background: linear-gradient(135deg, var(--brand), #7a5cff);
      box-shadow: 0 12px 30px rgba(15, 98, 254, 0.22);
    }

    nav ul,
    .utility-list,
    .card-actions,
    .pill-list,
    .deal-meta {
      list-style: none;
      padding: 0;
      margin: 0;
    }

    .nav-links {
      display: flex;
      align-items: center;
      gap: 1.25rem;
      color: var(--muted);
      font-weight: 600;
    }

    .nav-links a:focus-visible,
    .footer-links a:focus-visible,
    .brand:focus-visible {
      outline: 3px solid var(--brand);
      outline-offset: 4px;
      border-radius: 12px;
    }

    main {
      display: block;
    }

    .hero {
      padding: 2rem 0 1.25rem;
    }

    .hero-grid {
      display: grid;
      grid-template-columns: minmax(0, 1.2fr) minmax(0, 0.8fr);
      gap: 1.5rem;
      align-items: stretch;
    }

    .hero-copy,
    .hero-panel,
    .content-card,
    .promo-card,
    .story-card,
    .product-card,
    .deal-card {
      background: rgba(255, 255, 255, 0.85);
      border: 1px solid var(--line);
      border-radius: var(--radius-xl);
      box-shadow: var(--shadow);
    }

    .hero-copy {
      padding: clamp(1.25rem, 2vw, 2rem);
      overflow: hidden;
      position: relative;
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      padding: 0.45rem 0.8rem;
      border-radius: 999px;
      background: var(--brand-soft);
      color: var(--brand-dark);
      font-weight: 700;
      font-size: 0.875rem;
    }

    .hero h1 {
      margin: 1rem 0 0.85rem;
      font-size: clamp(2.3rem, 5vw, 4.85rem);
      line-height: 0.96;
      letter-spacing: -0.05em;
      max-width: 11ch;
    }

    .hero p {
      margin: 0;
      max-width: 62ch;
      color: var(--muted);
      font-size: 1.05rem;
    }

    .hero-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.875rem;
      margin-top: 1.35rem;
    }

    .button {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 0.5rem;
      min-height: 2.8rem;
      padding: 0.85rem 1.15rem;
      border-radius: 999px;
      border: 1px solid transparent;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      transition: transform 160ms ease, box-shadow 160ms ease, background-color 160ms ease, color 160ms ease;
    }

    .button-primary {
      background: var(--brand);
      color: #fff;
      box-shadow: 0 14px 28px rgba(15, 98, 254, 0.22);
    }

    .button-secondary {
      background: #fff;
      border-color: var(--line);
      color: var(--text);
    }

    .button:focus-visible {
      outline: 3px solid #0b5fff;
      outline-offset: 3px;
    }

    .hero-panel {
      padding: 1rem;
      display: grid;
      gap: 1rem;
      align-content: start;
      background: linear-gradient(180deg, rgba(255, 255, 255, 0.96), rgba(238, 243, 255, 0.92));
    }

    .visual-stack {
      min-height: 19rem;
      border-radius: 24px;
      background:
        radial-gradient(circle at 75% 25%, rgba(255, 122, 89, 0.24), transparent 24%),
        linear-gradient(145deg, rgba(15, 98, 254, 0.95), rgba(84, 111, 255, 0.76));
      color: #fff;
      padding: 1.25rem;
      position: relative;
      overflow: hidden;
      display: grid;
      align-items: end;
    }

    .visual-stack::before,
    .visual-stack::after {
      content: "";
      position: absolute;
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.14);
      filter: blur(2px);
    }

    .visual-stack::before {
      inset: 1.2rem auto auto 1rem;
      width: 5rem;
      height: 5rem;
    }

    .visual-stack::after {
      right: -1rem;
      bottom: -0.8rem;
      width: 8rem;
      height: 8rem;
    }

    .visual-copy {
      position: relative;
      z-index: 1;
      max-width: 18rem;
    }

    .visual-copy strong {
      display: block;
      font-size: 1.25rem;
      margin-bottom: 0.35rem;
    }

    .stat-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 0.75rem;
    }

    .stat {
      padding: 0.9rem;
      border-radius: 18px;
      background: var(--surface);
      border: 1px solid var(--line);
    }

    .stat strong {
      display: block;
      font-size: 1.2rem;
    }

    .stat span {
      color: var(--muted);
      font-size: 0.88rem;
    }

    .toolbar {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      margin: 2rem 0 0.85rem;
    }

    .toolbar p {
      margin: 0;
      color: var(--muted);
    }

    .section-title {
      margin: 0;
      font-size: clamp(1.45rem, 2vw, 2rem);
      letter-spacing: -0.03em;
    }

    .section {
      padding: 1.25rem 0 0;
    }

    .grid {
      display: grid;
      gap: 1rem;
    }

    .product-grid {
      grid-template-columns: repeat(4, minmax(0, 1fr));
    }

    .deal-grid,
    .story-grid {
      grid-template-columns: repeat(3, minmax(0, 1fr));
    }

    .product-card {
      overflow: hidden;
      display: grid;
    }

    .product-media,
    .story-media,
    .deal-banner {
      min-height: 12rem;
      border-bottom: 1px solid var(--line);
      background:
        radial-gradient(circle at 20% 20%, rgba(255, 255, 255, 0.45), transparent 24%),
        linear-gradient(145deg, var(--brand-soft), #f7f0ff);
      position: relative;
      overflow: hidden;
    }

    .product-media::before,
    .story-media::before,
    .deal-banner::before {
      content: "";
      position: absolute;
      inset: auto auto 1rem 1rem;
      width: 5.25rem;
      height: 5.25rem;
      border-radius: 22px;
      background: rgba(255, 255, 255, 0.66);
      border: 1px solid rgba(255, 255, 255, 0.7);
      box-shadow: 0 14px 28px rgba(15, 98, 254, 0.12);
    }

    .product-media[data-tone="coral"] {
      background: radial-gradient(circle at 20% 20%, rgba(255, 255, 255, 0.35), transparent 24%), linear-gradient(145deg, #ffd7ce, #fff3ef);
    }

    .product-media[data-tone="teal"] {
      background: radial-gradient(circle at 20% 20%, rgba(255, 255, 255, 0.35), transparent 24%), linear-gradient(145deg, #d4fff3, #effcf8);
    }

    .product-media[data-tone="gold"] {
      background: radial-gradient(circle at 20% 20%, rgba(255, 255, 255, 0.35), transparent 24%), linear-gradient(145deg, #fff2d6, #fffaf0);
    }

    .product-media[data-tone="ink"] {
      background: radial-gradient(circle at 20% 20%, rgba(255, 255, 255, 0.35), transparent 24%), linear-gradient(145deg, #dde5ff, #eff3ff);
    }

    .product-content,
    .promo-content,
    .story-content,
    .deal-content {
      padding: 1rem;
    }

    .kicker {
      display: inline-flex;
      align-items: center;
      gap: 0.4rem;
      color: var(--brand-dark);
      font-size: 0.8rem;
      font-weight: 800;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    .product-content h3,
    .deal-content h3,
    .story-content h3 {
      margin: 0.35rem 0 0;
      font-size: 1.05rem;
      letter-spacing: -0.02em;
    }

    .product-content p,
    .deal-content p,
    .story-content p,
    .product-meta {
      color: var(--muted);
    }

    .product-meta {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      margin: 0.9rem 0 0;
      font-size: 0.92rem;
    }

    .price {
      color: var(--text);
      font-weight: 800;
      font-size: 1.05rem;
    }

    .card-actions {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 0.65rem;
      padding: 0 1rem 1rem;
      margin-top: auto;
    }

    .card-actions .button {
      width: 100%;
      border-radius: 14px;
      min-height: 2.6rem;
      font-size: 0.95rem;
    }

    .button-ghost {
      background: var(--surface-3);
      border-color: var(--line);
      color: var(--text);
    }

    .content-card {
      padding: 1rem;
    }

    .promo-card {
      display: grid;
      grid-template-columns: minmax(0, 1.1fr) minmax(15rem, 0.9fr);
      gap: 1rem;
      overflow: hidden;
    }

    .promo-text {
      padding: 1.1rem 1rem 1.1rem 1.15rem;
    }

    .promo-text h3 {
      margin: 0.3rem 0 0.55rem;
      font-size: 1.35rem;
      letter-spacing: -0.03em;
    }

    .promo-text p {
      margin: 0;
      color: var(--muted);
      max-width: 46ch;
    }

    .promo-rail {
      padding: 1rem;
      background: linear-gradient(180deg, #fff, #edf4ff);
      display: grid;
      align-content: center;
      gap: 0.8rem;
      border-left: 1px solid var(--line);
    }

    .deal-card,
    .story-card {
      overflow: hidden;
    }

    .deal-banner[data-tone="lavender"] {
      background: linear-gradient(145deg, #f3e8ff, #fcf8ff);
    }

    .deal-banner[data-tone="sand"] {
      background: linear-gradient(145deg, #fff0d6, #fffaf0);
    }

    .deal-banner[data-tone="mint"] {
      background: linear-gradient(145deg, #dff9ef, #f4fffb);
    }

    .deal-banner {
      min-height: 11rem;
    }

    .story-media[data-tone="berry"] {
      background: linear-gradient(145deg, #ffe0ea, #fff6f9);
    }

    .story-media[data-tone="slate"] {
      background: linear-gradient(145deg, #dce7ff, #f6f8ff);
    }

    .story-media[data-tone="spruce"] {
      background: linear-gradient(145deg, #daf4ea, #f5fbf8);
    }

    .small-link {
      display: inline-flex;
      align-items: center;
      gap: 0.35rem;
      color: var(--brand-dark);
      font-weight: 700;
      margin-top: 0.8rem;
    }

    .pill-list {
      display: flex;
      flex-wrap: wrap;
      gap: 0.6rem;
      margin-top: 1rem;
    }

    .pill {
      padding: 0.55rem 0.8rem;
      border-radius: 999px;
      border: 1px solid var(--line);
      background: rgba(255, 255, 255, 0.9);
      color: var(--muted);
      font-weight: 600;
      font-size: 0.9rem;
    }

    .status {
      position: fixed;
      left: 50%;
      bottom: 1rem;
      transform: translateX(-50%);
      width: min(100%, 30rem);
      padding: 0.9rem 1rem;
      border-radius: 999px;
      background: rgba(24, 34, 48, 0.95);
      color: #fff;
      box-shadow: var(--shadow);
      opacity: 0;
      pointer-events: none;
      transition: opacity 180ms ease, transform 180ms ease;
    }

    .status.is-visible {
      opacity: 1;
      transform: translateX(-50%) translateY(-0.25rem);
    }

    footer {
      margin-top: 3rem;
      padding: 2rem 0 2.5rem;
      border-top: 1px solid var(--line);
      background: rgba(255, 255, 255, 0.5);
    }

    .footer-grid {
      display: grid;
      gap: 1.25rem;
      grid-template-columns: 1.1fr 0.9fr 0.9fr;
      align-items: start;
    }

    .footer-links {
      display: grid;
      gap: 0.65rem;
      color: var(--muted);
      font-weight: 500;
    }

    .fineprint {
      margin: 0.75rem 0 0;
      color: var(--muted);
      font-size: 0.95rem;
      max-width: 44ch;
    }

    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    .sr-only:focus,
    .sr-only:focus-visible {
      position: static;
      width: auto;
      height: auto;
      margin: 1rem;
      clip: auto;
      white-space: normal;
      display: inline-flex;
    }

    @media (prefers-reduced-motion: no-preference) {
      .button:hover,
      .small-link:hover {
        transform: translateY(-1px);
      }

      .product-card,
      .deal-card,
      .story-card,
      .promo-card {
        transition: transform 180ms ease, box-shadow 180ms ease;
      }

      .product-card:hover,
      .deal-card:hover,
      .story-card:hover,
      .promo-card:hover {
        transform: translateY(-2px);
        box-shadow: 0 24px 55px rgba(24, 34, 48, 0.12);
      }
    }

    @media (max-width: 1000px) {
      .hero-grid,
      .promo-card,
      .footer-grid {
        grid-template-columns: 1fr;
      }

      .product-grid,
      .deal-grid,
      .story-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }

      .promo-rail {
        border-left: 0;
        border-top: 1px solid var(--line);
      }
    }

    @media (max-width: 640px) {
      .topbar {
        min-height: 4.35rem;
        flex-wrap: wrap;
        padding: 0.7rem 0;
      }

      nav {
        width: 100%;
      }

      .nav-links {
        gap: 0.6rem 0.9rem;
        font-size: 0.93rem;
        flex-wrap: wrap;
      }

      .hero {
        padding-top: 1.25rem;
      }

      .hero h1 {
        max-width: 12ch;
      }

      .product-grid,
      .deal-grid,
      .story-grid {
        grid-template-columns: 1fr;
      }

      .stat-grid {
        grid-template-columns: 1fr;
      }

      .card-actions {
        grid-template-columns: 1fr;
      }

      .status {
        left: 1rem;
        right: 1rem;
        width: auto;
        max-width: none;
        transform: none;
      }

      .status.is-visible {
        transform: translateY(-0.25rem);
      }
    }

    @media (forced-colors: active) {
      :root {
        --bg: Canvas;
        --surface: Canvas;
        --surface-2: Canvas;
        --surface-3: Canvas;
        --text: CanvasText;
        --muted: CanvasText;
        --line: CanvasText;
        --brand: LinkText;
        --brand-dark: LinkText;
        --brand-soft: Canvas;
      }

      body,
      header,
      footer,
      .hero-copy,
      .hero-panel,
      .content-card,
      .promo-card,
      .story-card,
      .product-card,
      .deal-card,
      .stat,
      .pill,
      .button,
      .skip-link,
      .status {
        forced-color-adjust: auto;
        box-shadow: none;
      }

      .button-primary {
        background: ButtonFace;
        color: ButtonText;
        border-color: ButtonText;
      }

      .button-secondary,
      .button-ghost {
        background: ButtonFace;
        color: ButtonText;
        border-color: ButtonText;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#maincontent">Skip to main content</a>

  <header>
    <div class="shell topbar">
      <a class="brand" href="/" aria-label="Northstar Retail home">
        <span class="brand-mark" aria-hidden="true">N</span>
        <span>Northstar Retail</span>
      </a>

      <nav aria-label="Primary">
        <ul class="nav-links">
          <li><a href="#featured-products">Featured</a></li>
          <li><a href="#deals">Deals</a></li>
          <li><a href="#editorial">Editorial</a></li>
        </ul>
      </nav>
    </div>
  </header>

  <main id="maincontent" tabindex="-1">
    <section class="hero">
      <div class="shell hero-grid">
        <div class="hero-copy">
          <span class="eyebrow">New season arrivals</span>
          <h1>Modern essentials for every day, styled with ease.</h1>
          <p>
            Discover elevated layers, everyday accessories, and limited-time deals curated for a clean, polished retail experience.
          </p>

          <div class="hero-actions">
            <a class="button button-primary" href="#featured-products">Shop featured</a>
            <a class="button button-secondary" href="#deals">See deals</a>
          </div>

          <ul class="pill-list" aria-label="Popular categories">
            <li><span class="pill">Outerwear</span></li>
            <li><span class="pill">Footwear</span></li>
            <li><span class="pill">Home goods</span></li>
            <li><span class="pill">Gifts</span></li>
          </ul>
        </div>

        <aside class="hero-panel" aria-label="Store highlights">
          <div class="visual-stack" aria-hidden="true">
            <div class="visual-copy">
              <strong>Free delivery over $75</strong>
              <span>Fast shipping, easy returns, and quality pieces made to mix and match.</span>
            </div>
          </div>

          <div class="stat-grid" aria-label="Store metrics">
            <div class="stat">
              <strong>120+</strong>
              <span>new arrivals</span>
            </div>
            <div class="stat">
              <strong>4.8/5</strong>
              <span>customer rating</span>
            </div>
            <div class="stat">
              <strong>24h</strong>
              <span>dispatch window</span>
            </div>
          </div>
        </aside>
      </div>
    </section>

    <section class="section" aria-labelledby="featured-heading" id="featured-products">
      <div class="shell">
        <div class="toolbar">
          <div>
            <h2 class="section-title" id="featured-heading">Featured products</h2>
            <p>Best-selling pieces with a refined, everyday fit.</p>
          </div>
        </div>

        <ul class="grid product-grid">
          <li>
            <article class="product-card">
              <div class="product-media" data-tone="ink" aria-hidden="true"></div>
              <div class="product-content">
                <span class="kicker">Featured</span>
                <h3><a href="/products/skyline-jacket">Skyline Jacket</a></h3>
                <p>Weather-ready, lightly insulated, and cut for clean layering.</p>
                <div class="product-meta">
                  <span class="price">$168</span>
                  <span>4 colors</span>
                </div>
              </div>
              <div class="card-actions">
                <button class="button button-primary add-to-cart" type="button" data-product="Skyline Jacket" aria-label="Add to cart: Skyline Jacket">Add to cart</button>
                <button class="button button-ghost save-item" type="button" data-product="Skyline Jacket" aria-pressed="false" aria-label="Save Skyline Jacket">Save</button>
              </div>
            </article>
          </li>

          <li>
            <article class="product-card">
              <div class="product-media" data-tone="teal" aria-hidden="true"></div>
              <div class="product-content">
                <span class="kicker">Trending</span>
                <h3><a href="/products/harbor-knit">Harbor Knit</a></h3>
                <p>Soft texture, relaxed fit, and a polished look for daily wear.</p>
                <div class="product-meta">
                  <span class="price">$84</span>
                  <span>Best value</span>
                </div>
              </div>
              <div class="card-actions">
                <button class="button button-primary add-to-cart" type="button" data-product="Harbor Knit" aria-label="Add to cart: Harbor Knit">Add to cart</button>
                <button class="button button-ghost save-item" type="button" data-product="Harbor Knit" aria-pressed="false" aria-label="Save Harbor Knit">Save</button>
              </div>
            </article>
          </li>

          <li>
            <article class="product-card">
              <div class="product-media" data-tone="coral" aria-hidden="true"></div>
              <div class="product-content">
                <span class="kicker">New</span>
