      statusNode.textContent = message;
      statusNode.classList.add("is-visible");
      window.clearTimeout(showStatus.timer);
      showStatus.timer = window.setTimeout(() => {
        statusNode.classList.remove("is-visible");
      }, 2200);
    }

    function updateCartLabel() {
      const total = [...cart.values()].reduce((sum, count) => sum + count, 0);
      document.title = total > 0 ? `Northstar Retail — Home (${total} in cart)` : "Northstar Retail — Home";
    }

    document.addEventListener("click", (event) => {
      const addButton = event.target.closest(".add-to-cart");
      const saveButton = event.target.closest(".save-item");

      if (addButton) {
        const product = addButton.dataset.product;
        const nextCount = (cart.get(product) || 0) + 1;
        cart.set(product, nextCount);
        updateCartLabel();
        showStatus(`${product} added to cart. ${nextCount} in your cart for this item.`);
        return;
      }

      if (saveButton) {
        const product = saveButton.dataset.product;
        const pressed = saveButton.getAttribute("aria-pressed") === "true";
        const nextPressed = !pressed;
        saveButton.setAttribute("aria-pressed", String(nextPressed));
        saveButton.textContent = nextPressed ? "Saved" : "Save";
        saveButton.setAttribute(
          "aria-label",
          nextPressed ? `Remove saved item: ${product}` : `Save ${product}`
        );
        showStatus(nextPressed ? `${product} saved for later.` : `${product} removed from saved items.`);
      }
    });
