  }));
  console.log(JSON.stringify(metrics));
  if (metrics.hasOverflowX) process.exit(1);

  await narrow.click('button.add-to-cart');
  const statusText = await narrow.textContent('#status');
  console.log('STATUS:' + statusText);
  await browser.close();
})();
